import com.project.system.service.*;import java.math.BigDecimal;import java.util.*;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;
public class MerchantIntegration{
 @Configuration @Import(WalletIdentityIntegration.Config.class) static class Config{@Bean public MerchantService merchant(){return new MerchantService();}}
 static int checks;static void check(boolean b,String n){if(!b)throw new AssertionError(n);checks++;System.out.println("PASS "+n);}static void reject(Runnable r,String n){try{r.run();}catch(IllegalArgumentException e){check(true,n);return;}throw new AssertionError(n);}
 public static void main(String[]args){try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(Config.class)){MerchantService m=c.getBean(MerchantService.class);WalletService w=c.getBean(WalletService.class);JdbcTemplate db=c.getBean(JdbcTemplate.class);long id=m.save(null,"测试商户A","CATERING","测试联系人","13800000001","测试地址","仅测试",1);check(m.info(id).get("merchant_no").toString().startsWith("SH"),"create unique merchant number");check(((Number)m.search("测试商户A",null,null,null,1).get("total")).intValue()>0,"search merchant");long pay=w.trade(2,"PAY",new BigDecimal("0.01"),id,null,UUID.randomUUID().toString(),1);m.save(id,"测试商户B","CATERING","测试联系人","13800000001","测试地址","仅测试",1);check("测试商户A".equals(db.queryForObject("select merchant_name_snapshot from campus_ledger where id=?",String.class,pay)),"rename preserves original transaction name");m.status(id,0,"测试停用",1);reject(()->w.trade(2,"PAY",new BigDecimal("0.01"),id,null,UUID.randomUUID().toString(),1),"disabled merchant rejects new consumption");w.trade(2,"REFUND",new BigDecimal("0.01"),null,pay,UUID.randomUUID().toString(),1);check(((Number)m.detail(id,1).get("total")).intValue()==2,"disabled merchant permits original refund and lists both records");m.status(id,1,"测试恢复",1);check(((Number)m.info(id).get("active")).intValue()==1,"enable merchant");reject(()->m.status(3,0,"test",1),"system merchant protected");reject(()->m.save(id,"测试","INVALID","x","12345","x","",1),"invalid category rejected");check(((List<?>)m.detail(id,1).get("audit")).size()==4,"create update disable enable audit");System.out.println("PASS TOTAL "+checks);}}
}
